RANDN_F32 = {1: randn_f32_1, 2: randn_f32_2, 5: randn_f32_5, 15: randn_f32_15, 16: randn_f32_16, 17: randn_f32_17, 31: randn_f32_31, 32: randn_f32_32, 33: randn_f32_33, 100: randn_f32_100}
RANDN_F64 = {1: randn_f64_1, 2: randn_f64_2, 5: randn_f64_5, 15: randn_f64_15, 16: randn_f64_16, 17: randn_f64_17, 31: randn_f64_31, 32: randn_f64_32, 33: randn_f64_33, 100: randn_f64_100}
RANDPERM = {1: randperm_1, 2: randperm_2, 3: randperm_3, 10: randperm_10, 50: randperm_50}

def close(got: List[float], exp: List[float], rtol: float, atol: float = 0.0) -> bool:
    if len(got) != len(exp):
        print("len mismatch", len(got), len(exp))
        return False
    for i in range(len(got)):
        g = got[i]
        e = exp[i]
        d = g - e
        if d < 0: d = -d
        ae = e if e >= 0 else -e
        if d > atol + rtol * ae:
            print("mismatch at", i, g, e)
            return False
    return True

def exact(got: List[float], exp: List[float]) -> bool:
    return close(got, exp, 0.0, 0.0)

# Box-Muller samples go through log/sqrt/cos/sin, whose last bit differs between
# libms (Apple libm vs glibc); real torch on each platform produces that platform's
# value, so compare those within 2 ulp of the stored dtype. Uniform/integer draws
# stay bit-exact.
def _ulp(x: float, f32: bool) -> float:
    import math
    m, e = math.frexp(x if x != 0.0 else 1e-300)
    return math.ldexp(1.0, e - (24 if f32 else 53))

def ulp_close(got: List[float], exp: List[float], f32: bool) -> bool:
    if len(got) != len(exp):
        return False
    for i in range(len(got)):
        if abs(got[i] - exp[i]) > 2.0 * _ulp(exp[i], f32):
            print("mismatch at", i, got[i], exp[i])
            return False
    return True

def ints(t: torch.Tensor) -> List[int]:
    return [int(v) for v in t.tolist()]

@test
def test_random():
    for n in [1, 2, 5, 15, 16, 17, 31, 32, 33, 100]:
        torch.manual_seed(n)
        assert ulp_close(torch.randn(n).tolist(), RANDN_F32[n], True)
        torch.manual_seed(n)
        assert ulp_close(torch.randn(n, dtype=torch.float64).tolist(), RANDN_F64[n], False)
    torch.manual_seed(7); assert exact(torch.rand(10).tolist(), rand_f32)
    torch.manual_seed(7); assert exact(torch.rand(10, dtype=torch.float64).tolist(), rand_f64)
    torch.manual_seed(7); assert exact(torch.empty(20).uniform_(-0.31, 0.57).tolist(), uniform_f32)
    torch.manual_seed(7); assert exact(torch.empty(20, dtype=torch.float64).uniform_(-0.31, 0.57).tolist(), uniform_f64)
    torch.manual_seed(7); assert ulp_close(torch.empty(3, 7).normal_(0.3, 2.5).tolist(), normal_f32, True)
    torch.manual_seed(7); assert ulp_close(torch.empty(3, 7, dtype=torch.float64).normal_(0.3, 2.5).tolist(), normal_f64, False)
    torch.manual_seed(7); assert exact(torch.empty(30).bernoulli_(0.3).tolist(), bern_f32)
    torch.manual_seed(7); assert exact(torch.empty(30, dtype=torch.float64).bernoulli_(0.3).tolist(), bern_f64)
    for n in [1, 2, 3, 10, 50]:
        torch.manual_seed(3)
        assert ints(torch.randperm(n)) == RANDPERM[n]
    torch.manual_seed(3); assert ints(torch.randint(-5, 17, (12,))) == randint_a
    g = torch.Generator().manual_seed(11)
    assert exact(torch.rand(5, generator=g).tolist(), gen_rand)
    assert exact(torch.randn(3, generator=g).tolist(), gen_randn_after)
    torch.manual_seed(0)
    a = torch.randn(3)
    b = torch.randn(3)
    assert exact(torch.cat([a, b]).tolist(), randn_seq)
    st = g.get_state()
    r1 = torch.rand(4, generator=g).tolist()
    g.set_state(st)
    assert exact(torch.rand(4, generator=g).tolist(), r1)

@test
def test_tensor_ops():
    x = torch.arange(24, dtype=torch.float32).reshape(2, 3, 4) / 7.0 - 1.3
    R = 2e-6
    assert x.shape == [2, 3, 4] and x.dtype == torch.float32 and x.dim() == 3 and x.numel() == 24
    assert close(x.sum(1).tolist(), x_sum_1, R)
    assert close(x.mean((0, 2), keepdim=True).tolist(), x_mean_02k, R)
    assert x.mean((0, 2), keepdim=True).shape == [1, 3, 1]
    assert close(x.var(2).tolist(), x_var_2, R)
    assert close(x.std(0, unbiased=False).tolist(), x_std_unb0, R)
    assert close(x.amax(1).tolist(), x_amax_1, R)
    assert ints(x.argmax(2)) == [v for r in x_argmax_2 for v in r]
    assert close(torch.softmax(x, 1).tolist(), x_softmax_1, R)
    assert close(torch.log_softmax(x, 2).tolist(), x_logsoftmax_2, R, 1e-6)
    assert close(torch.logsumexp(x, 2).tolist(), x_lse_2, R)
    assert exact(x.permute(2, 0, 1).contiguous().tolist(), x_perm)
    assert exact(x[1, 1:, ::2].tolist(), x_idx)
    assert exact(x[:, None, -1, torch.tensor([0, 3])].tolist(), x_idx2)
    assert exact(x[x > 0.5].tolist(), x_mask)
    assert close(x.cumsum(2).tolist(), x_cumsum, R, 1e-6)
    assert close((x @ x.transpose(1, 2)).tolist(), x_matmul, R, 1e-6)
    assert close(torch.einsum("bij,bkj->bik", x, x).tolist(), x_einsum, R, 1e-6)
    assert close(torch.exp(x).tolist(), x_exp, R)
    assert close(torch.tanh(x).tolist(), x_tanh, R)
    assert close(torch.sigmoid(x).tolist(), x_sigmoid, R)
    assert close(torch.erf(x).tolist(), x_erf, R, 1e-6)  # torch NEON erf is an A&S approximation (abs err ~1e-7)
    assert exact(x.clamp(-0.5, 0.7).tolist(), x_clamp)
    assert exact(x.flip(2).tolist(), x_flip)
    assert exact(x.roll(1, 2).tolist(), x_roll)
    assert exact(x[0, :2, :2].repeat(2, 3).tolist(), x_repeat)
    assert exact(x[0].unfold(1, 2, 1).tolist(), x_unfold)
    assert exact(x[0, 0].flip(0).sort().values.tolist(), x_sort)
    assert exact(x.reshape(-1).topk(3).values.tolist(), x_topk)
    assert close([x.norm().item()], [x_norm], R)
    assert exact(torch._tensor._pad(x, [2, 1], "reflect").tolist(), pad_reflect)
    assert exact((torch.arange(6) / 4).tolist(), int_div)
    assert ints(torch.arange(-3, 4) // 2) == floor_div
    d = torch.arange(10, dtype=torch.float64) * 0.1
    assert close([d.sum().item()], [f64_sum], 1e-15)
    assert close([d.mean().item()], [f64_mean], 1e-15)
    assert close(torch.linspace(-1.3, 2.7, 7).tolist(), linspace, 1e-7)
    # views share memory
    v = x.view(6, 4)
    v[0, 0] = 5.0
    assert x[0, 0, 0].item() == 5.0
    # numpy round trip
    a = np.arange(6.0).reshape(2, 3)
    t = torch.from_numpy(a)
    assert t.dtype == torch.float64 and t.shape == [2, 3]
    b = t.numpy(float, 2)
    assert b[1, 2] == 5.0
    assert torch.tensor([[1, 2], [3, 4]]).dtype == torch.int64
    assert torch.tensor([True, False]).dtype == torch.bool
    assert (torch.ones(2, dtype=torch.int64) + 1.5).dtype == torch.float32

@test
def test_autograd():
    w = (torch.arange(12, dtype=torch.float64).reshape(3, 4) / 5 - 1).requires_grad_()
    v = (torch.arange(4, dtype=torch.float64) / 3 + 0.2).requires_grad_()
    y = (torch.tanh(w @ v).pow(2).sum() + torch.softmax(w, 1)[:, 1].log().mean()
         + (w * v).exp().amax(1).sum() + w.std() + torch.sigmoid(w[1:, ::2]).sum())
    y.backward()
    R = 1e-12
    assert close([y.item()], [ag_y], R)
    assert close(w.grad.tolist(), ag_gw, R, 1e-14)
    assert close(v.grad.tolist(), ag_gv, R, 1e-14)
    a = torch.linspace(0.1, 2.0, 6, dtype=torch.float64).reshape(2, 3).requires_grad_()
    z = (torch.cat([a, a * 2], 0).reshape(3, 4).t()[1:].sqrt().sum()
         + torch.stack([a, a.flip(1)], 2).sum(2).prod() + a.clamp(0.5, 1.5).sum()
         + torch.where(a > 1.0, a ** 3, -a).sum() + a.unsqueeze(0).expand(3, 2, 3).sum())
    z.backward()
    assert close([z.item()], [ag_z], R)
    assert close(a.grad.tolist(), ag_ga, R, 1e-14)
    with torch.no_grad():
        q = w * 2.0
    assert not q.requires_grad

@test
def test_linalg_fft():
    A = torch.tensor([[4.0, 1.0, 0.5], [1.0, 3.0, 0.2], [0.5, 0.2, 2.0]], dtype=torch.float64, requires_grad=True)
    r = torch.linalg.eigh(A)
    (r.eigenvalues.sum() + (r.eigenvectors ** 3).sum() + torch.linalg.inv(A).sum() + torch.linalg.cholesky(A).sum()
     + torch.linalg.slogdet(A).logabsdet + torch.linalg.svd(A).S.sum()).backward()
    assert close(r.eigenvalues.tolist(), la_evals, 1e-12)
    assert close(A.grad.tolist(), la_grad, 1e-10, 1e-12)
    x = torch.linspace(0., 1., 8, dtype=torch.float64, requires_grad=True)
    X = torch.fft.rfft(x)
    y = (X.abs() ** 2).sum() + torch.fft.irfft(X * 2.0, n=8).sum() + torch.fft.fft(x).real.sum()
    y.backward()
    assert close(torch.view_as_real(X).tolist(), fft_X, 1e-12, 1e-14)
    assert close([y.item()], [fft_y], 1e-12)
    assert close(x.grad.tolist(), fft_grad, 1e-12)
    xf = torch.arange(10, dtype=torch.float32) / 3.0
    assert close(torch.view_as_real(torch.fft.rfft(xf, norm="forward")).tolist(), rfft_f32, 1e-5, 1e-7)

@test
def test_stft():
    xs = torch.sin(torch.arange(200, dtype=torch.float64) * 0.1) + torch.arange(200, dtype=torch.float64) * 0.01
    ws = torch.hann_window(32, dtype=torch.float64)
    S = torch.stft(xs, 32, 8, window=ws, return_complex=True)
    assert S.shape == stft_shape
    assert close(torch.view_as_real(S).tolist(), stft_re, 1e-12, 1e-12)
    assert close(torch.istft(S, 32, 8, window=ws, length=200).tolist(), istft, 1e-12, 1e-13)
    S2 = torch.stft(torch.stack([xs, xs * 2]).float(), 16, window=torch.hann_window(16), return_complex=True, center=False)
    assert close(S2.abs().tolist(), stft2_abs, 1e-5, 1e-5)

test_random()
test_stft()
test_linalg_fft()
test_tensor_ops()
test_autograd()
